package main

import (
	"flag"
	"fmt"
	"os"
	"strings"

	"github.com/mark3labs/mcp-go/server"
	mcptools "github.com/mvanhorn/printing-press-library/library/social-and-messaging/naver-blog/internal/mcp"
)

const defaultHTTPAddr = "127.0.0.1:7720"

func main() {
	transport := flag.String("transport", envOrDefault("NAVER_BLOG_MCP_TRANSPORT", "stdio"), "MCP transport: stdio or http")
	addr := flag.String("addr", envOrDefault("NAVER_BLOG_MCP_ADDR", defaultHTTPAddr), "HTTP listen address for --transport=http")
	flag.Parse()

	s := server.NewMCPServer(
		"Naver Blog",
		"1.0.0",
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)
	mcptools.RegisterNovelTools(s)

	switch strings.ToLower(strings.TrimSpace(*transport)) {
	case "", "stdio":
		if err := server.ServeStdio(s); err != nil {
			exitWithError("MCP stdio server error", err)
		}
	case "http", "streamable-http", "streamable_http":
		httpServer := server.NewStreamableHTTPServer(s, server.WithEndpointPath("/mcp"))
		fmt.Fprintf(os.Stderr, "MCP streamable HTTP transport listening on http://%s/mcp\n", *addr)
		if err := httpServer.Start(*addr); err != nil {
			exitWithError("MCP streamable HTTP server error", err)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown transport %q (expected stdio or http)\n", *transport)
		os.Exit(2)
	}
}

func envOrDefault(key, fallback string) string {
	if v, ok := os.LookupEnv(key); ok && strings.TrimSpace(v) != "" {
		return v
	}
	return fallback
}

